/* eslint-disable-next-line @typescript-eslint/no-unused-vars */
namespace Innovasys.Content.Features {

    export class DxNetDocumentFeature extends DxBaseDocumentFeature implements IDocumentFeature {

        public getName(): string {
            return "dx-net";
        }

        public populateResponsiveConfiguration(configuration: ResponsiveConfiguration): void {
            super.populateResponsiveConfiguration(configuration);
            if (configuration.profileName === "mobile" || configuration.profileName === "tablet") {
                switch (configuration.profileName) {
                    case "tablet":
                        configuration.clickTargets.push(new ResponsiveClickTarget("a[href='#top']", ResponsiveClickTargetKind.block));
                        break;
                    case "mobile":
                        break;
                    // No default
                }
                configuration.clickTargets.push(
                    new ResponsiveClickTarget(
                        "#i-inheritance-section-content a, #i-hierarchy-section-content a",
                        ResponsiveClickTargetKind.inline));
            }
        }

    }

    export class DxNetDocumentFeatureFactory {

        public createInstance(documentInstance: Document): IDocumentFeature {
            // Always enabled
            return new DxNetDocumentFeature(documentInstance);
        }

    }

}

Innovasys.Content.DocumentFeatureConfiguration.registerDocumentFeatureFactory(
    new Innovasys.Content.Features.DxNetDocumentFeatureFactory());
