/* eslint @typescript-eslint/no-unused-vars: "off" */
namespace Innovasys.Content {

    const browserInfoConstants = {
        minHeightChange: 10,
        ie7Version: 7
    };

    export class BrowserInfo {
        public name: string;
        public version: number;
        constructor() {
            const ua = BrowserInfo.getUserAgent().toLowerCase();
            const match: any = /(chrome)[ /]([\w.]+)/.exec(ua) ||
                /(webkit)[ /]([\w.]+)/.exec(ua) ||
                /(opera)(?:.*version|)[ /]([\w.]+)/.exec(ua) ||
                /(msie) ([\w.]+)/.exec(ua) ||
                ua.indexOf("compatible") < 0 && /(mozilla)(?:.*? rv:([\w.]+)|)/.exec(ua) ||
                [];
            this.name = match[1] || "";
            const versionIndex = 2;
            this.version = parseInt(match[versionIndex] || "0", 10);
        }

        /**
         * Returns the current user agent string
         */
        public static getUserAgent(): string {
            return navigator.userAgent;
        }
    }

    export interface ILocationInfo {
        href: string;
        protocol: string;
        search?: string;
        hash?: string;
        hostname?: string;
        pathname?: string;
    }

    export class Browser {
        /** Indicates that we are running in a design time environment (i.e. the editor) */
        public static isDesignTime = false;
        /** Indicates that animations should be disabled */
        public static isAnimationDisabled = false;
	public static isAutoResponsive = false;
        /** Provides access to more information about the browser agent etc. */
        public static info = new BrowserInfo();
        /** Index for dynamically loaded stylesheets */
        public static dynamicallyLoadedFileIndex = 0;

        private static readonly _idCharacters = "_0123456789ABCDEFGHIJKLMNOPQRSTUVWXTZabcdefghiklmnopqrstuvwxyz".split("");

        /**
         * Return Microsoft Internet Explorer (major) version number, or 0 for others.
         */
        public static msIeVersion(): number {
            if (Browser.info.name === "msie") {
                // is Microsoft Internet Explorer; return version number
                return Browser.info.version;
            } else {
                return 0;    // is other browser
            }
        }

        /**
         * Get a document instance from a given page element.
         */
        public static getDocumentInstance<TDocument extends Document>(element: JQuery | HTMLElement): TDocument {
            let elementSelector: JQuery;
            if (!(element instanceof jQuery)) {
                elementSelector = $(element);
            } else {
                elementSelector = element as JQuery;
            }
            // Find the container element
            let root: JQuery = elementSelector.hasClass("content-root") ? elementSelector : elementSelector.parents(".content-root");
            if (root.length === 0) {
                root = $("body");
            } else {
                root = $(root.get(0));
            }
            // Now we have the root, check for a document object
            if (root.data("innovasys-document") != null) {
                return root.data("innovasys-document") as TDocument;
            } else {
                // No existing document, create a new one
                const newDocument = new Document(root.get(0));
                root.data("innovasys-document", newDocument);

                return newDocument as TDocument;
            }
        }

        /**
         * Returns basic information about the current browser location.
         */
        public static getLocationInfo(): ILocationInfo {
            return location;
        }

        /**
         * Return the current document compatMode value.
         */
        public static getCompatMode(): string {
            return document.compatMode;
        }

        /**
         * Reload the current page.
         */
        public static reload(): void {
            location.reload();
        }

        /**
         * Replace the current location.
         */
        public static replaceLocation(newLocation: string): void {
            if (window.history.replaceState) {
                try {
                    window.history.replaceState("", "", `#${newLocation}`);
                } catch (ex) {
                    // May fail with security exception on local file system
                }
            } else {
                window.location.replace(`#${newLocation}`);
            }
        }

        /**
         * Navigate to a new url.
         * @param url The url to navigate to.
         * @param replace Pass true in order to replace the current entry in the browser history.
         */
        public static navigateTo(url: string, replace: boolean): void {
            if (replace) {
                window.location.replace(url);
            } else {
                window.location.href = url;
            }
        }

        /**
         * Cross browser helper for stopping event propagation.
         */
        public static stopPropagation(e: JQueryEventObject): void {
            if (e.stopPropagation) {
                e.stopPropagation();
            } else {
                e.returnValue = false;
            }
        }

        /**
         * Loads a stylesheet from the specified Url.
         */
        public static loadStylesheet(
            stylesheetUrl: string,
            stylesheetId: string,
            beforeElementId: string,
            onLoaded: (_: string) => void = null): string {

            const id = `file${this.dynamicallyLoadedFileIndex}`;
            this.dynamicallyLoadedFileIndex++;

            const attributes = { "data-stylesheet-id": stylesheetId };
            yepnope.injectCss({ href: stylesheetUrl, attrs: attributes }, () => {
                onLoaded(id);
            });

            return id;

        }

        /**
         * Loads a script file from the specified Url.
         */
        public static loadScript(
            scriptUrl: string,
            scriptId: string,
            beforeElementId: string,
            onLoaded: (_: string) => void = null): string {

            const id = `file${this.dynamicallyLoadedFileIndex}`;
            this.dynamicallyLoadedFileIndex++;

            const attributes = { "data-script-id": scriptId };
            yepnope.injectJs({ src: scriptUrl, attrs: attributes }, () => {
                onLoaded(id);
            });

            return id;

        }

        public static resizeIFrames(selector: JQuery, ignoreOffScreen = false): number {

            let maxHeight = 0;
            let minAllowedHeight: number;

            try {
                minAllowedHeight = $(window.top).height();
            } catch (ex) {
                minAllowedHeight = $(window).height();
            }

            $("iframe", selector).each((index: number, element: HTMLIFrameElement): void => {
                let currentHeight = 0;
                if ($(element).is(":visible") && (ignoreOffScreen || $(element).offset().left >= 0)) {
                    // Only resize if visible
                    let doc: Document = null;
                    try {
                        doc = element.contentDocument
                            ? element.contentDocument
                            : (element.contentWindow.document || (element as any).document);
                    } catch (exDocument) {
                        // Security may prevent access if frame hasn't loaded or is cross origin
                    }
                    if (doc != null) {
                        // Firefox throws an error here, so we trap and fallback
                        try {
                            currentHeight = $(doc).height();
                        } catch (exHeight) {
                            currentHeight = minAllowedHeight;
                        }
                    } else {
                        currentHeight = minAllowedHeight;
                    }
                    let lastHeight = $(element).data("last-height");
                    if (!lastHeight) {
                        lastHeight = 0;
                    }
                    const heightDifference = currentHeight - lastHeight;
                    if (heightDifference > browserInfoConstants.minHeightChange
                        || (heightDifference < 0 && heightDifference < browserInfoConstants.minHeightChange)) {

                        const parent = $(element).parent();
                        if (parent.get(0).tagName === "DIV" && currentHeight < parent.height()) {
                            // Resize to at least the containing DIV height
                            currentHeight = parent.height();
                        }
                        if (currentHeight < minAllowedHeight) {
                            // Make sure at least as high as the window
                            currentHeight = minAllowedHeight;
                        }
                        $(element).height(`${currentHeight}px`);
                        $(element).data("last-height", currentHeight);
                    }
                } else if (!$(element).is(":visible")) {
                    // Not visible, collapse to zero
                    $(element).height(0);
                    $(element).data("last-height", 0);
                }
                if (currentHeight > maxHeight) {
                    // Record the maximum iframe height
                    maxHeight = currentHeight;
                }
            });

            const busy: JQuery = $("#i-busy");
            if (busy.length !== 0) {
                busy.height(maxHeight);
            }

            return maxHeight;

        }

        public static showElement(query: JQuery<Element>, tagName: string): void {
            // Firefox does not remove a display: none on show so we check for that specifically here
            query.show();
            if (tagName === "body") {
                $("body").css("display", "block");
            }
        }

        /**
         * Works around a jQuery setAttribute bug for a specific IE mode used by MSHV and Help 2.x (with IE11 installed)
         */
        public static checkForIe7ModeJqueryBug(): void {
            if (Browser.info.name === "msie" && Browser.info.version <= browserInfoConstants.ie7Version) {
                const mshvAttributeSetWorkaround = {
                    set: (elem: Element, value: any, name: string): any => {
                        elem.setAttribute(name, value);

                        return elem.getAttributeNode(name);
                    }
                };
                if ($ != null && ($ as any).attrHooks != null) {
                    const attributeHooks: any = ($ as any).attrHooks;
                    attributeHooks["aria-describedby"] = mshvAttributeSetWorkaround;
                    attributeHooks["aria-live"] = mshvAttributeSetWorkaround;
                    attributeHooks["aria-atomic"] = mshvAttributeSetWorkaround;
                    attributeHooks["aria-hidden"] = mshvAttributeSetWorkaround;
                }
            }
        }

        public static getQueryStringParameter(name: string): string {
            name = name.replace(/[[]/, "\\[").replace(/[\]]/, "\\]");
            const regex = new RegExp(`[\\?&]${name}=([^&#]*)`);
            const results = regex.exec(Browser.getLocationInfo().search);

            return results == null ? null : decodeURIComponent(results[1].replace(/\+/g, " "));
        }

        public static isCompiledHelp(): boolean {
            const currentHref = `${Browser.getLocationInfo().href}.`;
            const currentProtocol = Browser.getLocationInfo().protocol;

            if (currentHref.indexOf("mk:@MSITStore") === 0) {
                return true;
            } else if (currentHref.indexOf("ms-its:") === 0) {
                return true;
            } else if (currentProtocol === "ms-help:") {
                return true;
            } else if (currentProtocol === "ms-xhelp:" ||
                currentHref.indexOf("ms.help?") !== -1 ||
                currentHref.indexOf("?method=page&") !== -1) {

                return true;
            }

            return false;
        }

        public static isEditor(): boolean {
            return location.protocol === "about:";
        }

        /**
         * Returns a unique id, randomnly generated and checked for uniqueness in the DOM
         */
        public static getUniqueId(): string {
            const idlength = 10;
            const getId = (): string => {
                let idValue = "";
                for (let i = 0; i < idlength; i++) {
                    idValue += Browser._idCharacters[Math.floor(Math.random() * Browser._idCharacters.length)];
                }

                return idValue;
            };
            let id = getId();
            while ($(`#${id}`).length > 0) {
                id = getId();
            }

            return id;
        }

        /**
         * Returns common feature settings
         */
        public static getCommonSettings(): IOverrides {
            return ((Innovasys as any).overrides || (Innovasys as any).settings) || {};
        }

        /**
         * Compares 2 version strings and returns an integer indicating the result. < 0 if a < b, > 0 if a > b, 0 if a = b
         */
        public static compareVersionStrings(a: string, b: string): number {
            const regExStrip0 = /(\.0+)+$/;
            const segmentsA = a.replace(regExStrip0, "").split(".");
            const segmentsB = b.replace(regExStrip0, "").split(".");
            const l = Math.min(segmentsA.length, segmentsB.length);

            for (let i = 0; i < l; i++) {
                const diff = parseInt(segmentsA[i], 10) - parseInt(segmentsB[i], 10);
                if (diff) {
                    return diff;
                }
            }

            return segmentsA.length - segmentsB.length;
        }

        /**
         * Creates or returns a <style> element to contain custom style markup
         */
        public static getDynamicStyleContainer(id: string): JQuery {
            let $dynamicStyleElement = $(`#${id}`);
            if ($dynamicStyleElement.length === 0) {
                $dynamicStyleElement = $(`<style type="text/css" id="${id}"></style>`);
                $("head").append($dynamicStyleElement);
            }

            return $dynamicStyleElement;
        }

        public static isElementInView(element: Element, fullyInView: boolean): boolean {
            if (element == null) {
                return false;
            }

            if (!$(element).is(":visible")) {
                return false;
            }

            const pageTop = $(window).scrollTop();
            const pageBottom = pageTop + $(window).height();
            const elementTop = $(element).offset().top;
            const elementBottom = elementTop + $(element).height();

            if (fullyInView) {
                return ((pageTop < elementTop) && (pageBottom > elementBottom));
            } else {
                return ((elementTop <= pageBottom) && (elementBottom >= pageTop));
            }
        }
    }

}

/* eslint @typescript-eslint/no-explicit-any: "off" */
const overrides: Innovasys.IOverrides = ((Innovasys as any).overrides || (Innovasys as any).settings);

if (document.compatMode !== "BackCompat"
    || !(location.protocol === "ms-xhelp:"
        || location.href.indexOf("ms.help?") !== -1
        || location.href.indexOf("?method=page&") !== -1)) {

    if (overrides == null || !overrides.isHideBodyDuringLoadDisabled) {
        // Prevent flickering by setting body to display:none during initialization
        document.write("<style type=\"text/css\">body{display:none;}</style>");
    } else if (overrides.isOverflowClippedDuringLoad) {
        // Prevent adding of a vertical scrollbar during load
        document.write("<style type=\"text/css\">body{overflow-y:hidden;}</style>");
    }
}
