/* eslint-disable-next-line @typescript-eslint/no-unused-vars */
namespace Innovasys.Content.Features {

    const dynamicTocConstants = {
        tocSplitterWidth: 14,
        maxSavedTocWidth: 1000,
        minSavedTocWidth: 50,

        newFolderNodeIconIndex: 3,
        folderNodeIconIndex: 1,
        newPageNodeIconIndex: 10,
        pageNodeIconIndex: 9
    };

    export class DynamicTocNode {
        /**
         * Unique node id
         */
        public id: string;
        /**
         * Title
         */
        public t: string;
        /**
         * Icon
         */
        public i: number;
        /**
         * Is New Indicator
         */
        public n: boolean;
        /**
         * Target url
         */
        public u: string;
        /**
         * Child Nodes
         */
        public childNodes: DynamicTocNode[];
        /**
         * Populated
         */
        public isPopulated: boolean;
        /**
         * Id of the container this node is contained in
         */
        public containerId: string;
        /**
         * Id of the parent node
         */
        public parentNodeId: string;
        /**
         * Container where child nodes are located
         */
        public cc: string;
        /**
         * True if the node is currently expanded
         */
        public isExpanded: boolean;
        /**
         * True if the node is selected
         */
        public isSelected: boolean;
    }

    export class DynamicTocDocumentFeature extends DocumentFeatureBase {

        private _allNodes: Record<string, DynamicTocNode> = {};
        private _loadedContainers: Record<string, boolean> = {};
        private _rootSelector: JQuery;

        public getName(): string {
            return "Dynamic ToC";
        }

        /* eslint-disable-next-line @typescript-eslint/no-unused-vars */
        public initializeContent(rootSelector: JQuery, isInitialLoad: boolean = false): void {
            if (Browser.isDesignTime || $("#i-dt-root", rootSelector).length === 0) {
                return;
            }

            const settings = this.getFeatureSettings();
            if (Browser.isCompiledHelp() || !settings.isEnabled) {
                $("#i-dt-root", rootSelector).hide();
            }

            /* eslint-disable-next-line @typescript-eslint/no-explicit-any */
            (Innovasys as any).DynamicToc = this;
            this._rootSelector = rootSelector;
            this.loadNodeContainer("c0", () => {
                // If there is an initial node to select, load it, expand the path to it and mark as selected
                if (typeof (settings.initialNodeId) != "undefined"
                    && settings.initialNodeId != null
                    && settings.initialNodeContainer != null) {

                    // Hide whilst selecting and expanding nodes
                    $("#i-toc-content", this._rootSelector).hide();
                    this.loadNodeToRoot(settings.initialNodeId, settings.initialNodeContainer, settings.initialNodeId);
                }
            });

            if (settings.isResizable) {
                $("#i-toc-content").resizable({
                    handles: "e",
                    resize: (event, ui) => {
                        this.setTocWidth($(ui.element).outerWidth() + dynamicTocConstants.tocSplitterWidth);
                        $(ui.element).css("left", "");
                    }
                });

                // Load width from storage
                const width = this.documentInstance.getLocalStorage().getAttribute("i-dynamic-toc-width");
                if (width != null && width < dynamicTocConstants.maxSavedTocWidth && width > dynamicTocConstants.minSavedTocWidth) {
                    const $tocContent = $("#i-toc-content");
                    const innerWidthDifference = $tocContent.outerWidth() - $tocContent.width();
                    $tocContent.width(width - innerWidthDifference - dynamicTocConstants.tocSplitterWidth);
                    this.setTocWidth(width);
                }
            }

        }

        /**
         * Adds a dynamic style to adjust the body margin to match the ToC width
         */
        private setTocWidth(width: number): void {
            if(!Browser.isAutoResponsive)
            {
                const styleContainer = Browser.getDynamicStyleContainer("i-dynamic-body-margin");
                styleContainer.html(`@media only screen and (min-width: 769px) { #i-body-content { margin-left: ${width}px; }`);
                this.documentInstance.getLocalStorage().setAttribute("i-dynamic-toc-width", width);
            }
        }

        /**
         * Loads the passed node id (currentNodeId), loading the container if necessary and then repeating
         * up the node hiearchy to the root. Once the node path is fully loaded, the path is expanded and
         * the node is marked as selected.
         */
        private loadNodeToRoot(currentNodeId: string, containerToLoadNext: string, targetNodeId: string) {
            const node = this.getNode(currentNodeId);
            if (this._loadedContainers[containerToLoadNext]) {
                if (node.parentNodeId === "n0" || node.id === "n0") {
                    // Now joined up to the root node
                    this.createElementsForNodeChildren(node, true);
                    const targetNode = this.getNode(targetNodeId);
                    this.ensureNodeChildrenPopulated(targetNode,
                        populatedNode => this.expandAndSelectNode(populatedNode.id));

                } else {
                    const parentNode = this.getNode(node.parentNodeId);
                    this.loadNodeToRoot(parentNode.id, parentNode.containerId, targetNodeId);
                }
            } else {
                this.loadNodeContainer(containerToLoadNext, () => {
                    this.loadNodeToRoot(currentNodeId, containerToLoadNext, targetNodeId);
                });
            }
        }

        private expandAndSelectNode(targetNodeId: string): void {
            // Expand down
            let nodeToExpand = this.getNode(targetNodeId);

            while (nodeToExpand != null) {
                if ((nodeToExpand.id === "n0" || nodeToExpand.cc) && !nodeToExpand.isExpanded) {
                    this.toggleNodeIsExpanded(nodeToExpand);
                }
                nodeToExpand = this.getNode(nodeToExpand.parentNodeId);
                if (typeof nodeToExpand == "undefined") {
                    nodeToExpand = null;
                }
            }

            // If the target node has children and a url, check the first child to
            //  see if it is for the same url and if so select that instead
            let nodeToSelect = this.getNode(targetNodeId);
            if (nodeToSelect.u != null &&
                nodeToSelect.childNodes != null &&
                nodeToSelect.childNodes.length > 0 &&
                nodeToSelect.childNodes[0].u === nodeToSelect.u) {

                nodeToSelect = nodeToSelect.childNodes[0];
            }
            this.setNodeSelected(nodeToSelect);

            $("#i-toc-content", this._rootSelector).show();
        }

        /**
         * Mark the node as selected (both in the node and related element)
         */
        private setNodeSelected(node: DynamicTocNode): void {
            node.isSelected = true;
            const $node = $(`#i-n-${node.id}`, this._rootSelector);
            if ($node.length > 0) {
                // Delay to ensure the ToC is visible
                setTimeout(() => {
                    if (!Browser.isElementInView($node.get(0), true)) {
                        $node.get(0).scrollIntoView();
                    }
                    $node.toggleClass("i-selected", true);
                }, 1);
            }
        }

        /**
         * Returns true if the node has been loaded (either partially or fully)
         */
        private nodeExists(nodeId: string): boolean {
            return this.getNode(nodeId) != null;
        }

        /**
         * Gets a previously loaded node. Returns null if the node has not been loaded
         */
        public getNode(nodeId: string): DynamicTocNode {
            const possibleNode = this._allNodes[nodeId];
            if (typeof possibleNode != "undefined" && possibleNode != null) {
                return possibleNode;
            }

            return null;
        }

        /**
         * Saves the passed node so that it can be fetched using getNode()
         */
        public setNode(node: DynamicTocNode): void {
            this._allNodes[node.id] = node;
        }

        /**
         * Injects node info, including child nodes. Called from container scripts.
         */
        public injectNodeInfo(nodeId: string, parentContainerId: string, childNodes: DynamicTocNode[]): void {

            let node = this.getNode(nodeId);

            if (node == null) {
                node = new DynamicTocNode();
                node.id = nodeId;
                if (node.id === "n0") {
                    node.cc = "c0";
                }
                this.setNode(node);
            }

            node.containerId = parentContainerId;

            node.childNodes = $.map(childNodes,
                (newChildNode: DynamicTocNode) => {
                    const currentNode = this.getNode(newChildNode.id);
                    if (currentNode != null) {
                        // Node already exists, merge new one
                        const newNode = { ...currentNode, ...newChildNode } as DynamicTocNode;

                        return newNode;
                    } else {
                        // No existing node
                        return newChildNode;
                    }
                });

            $.each(node.childNodes,
                (index: number, childNode: DynamicTocNode) => {
                    childNode.parentNodeId = node.id;
                    this.setNode(childNode);
                });

            // Only create elements when this node is joined up to the parent
            if (node.id === "n0" || (typeof node.parentNodeId != "undefined" && this.nodeExists(node.parentNodeId))) {
                this.createElementsForNodeChildren(node);
            }
        }

        /**
         * Loads a node container script, executing an optional afterLoadCallback once the script is loaded.
         */
        private loadNodeContainer(containerId: string, afterLoadCallback?: (loadedContainerId: string) => void) {
            Browser.loadScript(`./_toc/${containerId}.js`,
                `dt-${containerId}`,
                null,
                () => {
                    this._loadedContainers[containerId] = true;
                    if (afterLoadCallback != null) {
                        afterLoadCallback(containerId);
                    }
                });
        }

        /**
         * Creates the DOM elements for the child nodes of the passed node. Set recurse to true to populate
         * the whole node hiearchy below the passed node.
         */
        private createElementsForNodeChildren(node: DynamicTocNode, recurse: boolean = false): void {

            if (!node.cc || node.childNodes == null) {
                // No children, or children not yet populated
                return;
            }

            if (!node.isPopulated) {

                const settings = this.getFeatureSettings();
                let list: JQuery;

                let parentNode: JQuery = null;

                if (node.id === "n0") {
                    list = $("#i-dt-root", this._rootSelector);
                } else {
                    // Find the node for the parent and add a child list to contain the children
                    const parentNodeId = `#i-n-${node.id}`;
                    parentNode = $(parentNodeId, this._rootSelector);
                    if (parentNode.length === 0) {
                        // Parent node does not exist yet
                        return;
                    }
                    list = $("<ul/>");
                }

                $.each(node.childNodes,
                    (index: number, childNode: DynamicTocNode) => {

                        const isNew: boolean = childNode.n;

                        const newListItem = $("<li/>", { id: `i-n-${childNode.id}` })
                            .data("node-id", childNode.id);

                        if (isNew) {
                            newListItem.addClass("i-is-new");
                        }

                        const newExpander = $("<ins/>",
                            {
                                /* eslint-disable-next-line quote-props */
                                "class": (childNode.cc ? "i-spacer i-expandorcollapse i-expand" : "i-spacer")
                            })
                            .on("click.dynamictoc",
                                (eventObject: JQueryEventObject): boolean => {
                                    eventObject.cancelBubble = true;

                                    return this.onNodeElementClick(eventObject.currentTarget as Element, true);
                                });

                        const newNodeAnchor = $("<a/>")
                            .html(childNode.t)
                            .attr("href", childNode.u != null ? childNode.u : "#")
                            .on("click.dynamictoc",
                                (eventObject: JQueryEventObject): boolean => {
                                    eventObject.cancelBubble = true;

                                    return this.onNodeElementClick(eventObject.currentTarget as Element, false);
                                });

                        newListItem.append(newExpander);

                        if (settings.isIconEnabled) {
                            const iconIndex: number = childNode.i == null ? -1 : childNode.i;
                            let iconClassIndex: number = iconIndex;

                            if (childNode.cc) {
                                if (iconIndex <= 0) {
                                    if (isNew) {
                                        iconClassIndex = dynamicTocConstants.newFolderNodeIconIndex;
                                    } else {
                                        iconClassIndex = dynamicTocConstants.folderNodeIconIndex;
                                    }
                                }
                            } else {
                                if (iconIndex <= 0) {
                                    if (isNew) {
                                        iconClassIndex = dynamicTocConstants.newPageNodeIconIndex;
                                    } else {
                                        iconClassIndex = dynamicTocConstants.pageNodeIconIndex;
                                    }
                                }
                            }

                            const icon: JQuery = $("<ins class=\"i-icon\"></ins>")
                                .addClass(`i-icon-${iconClassIndex}`);

                            newListItem.append(icon);
                        }

                        newListItem.append(newNodeAnchor);
                        list.append(newListItem);
                    });

                if (parentNode != null) {
                    parentNode.append(list);
                } else {
                    list.addClass("i-visible");
                }

                // Set flag to indicate populated
                node.isPopulated = true;
            }

            if (recurse && node.childNodes != null) {
                $.each(node.childNodes,
                    (index: number, childNode: DynamicTocNode) => {
                        this.createElementsForNodeChildren(childNode, true);
                    });
            }
        }

        /**
         * Node element click handler
         */
        private onNodeElementClick(element: Element, isExpandOnly: boolean): boolean {
            const $element = $(element).parent("li");
            const node = this.getNode($element.data("node-id"));
            if (node.u != null && !isExpandOnly) {
                Browser.navigateTo(node.u, false);
            } else if (node.cc != null) {
                this.ensureNodeChildrenPopulated(node, populatedNode => {
                    // Toggle expand
                    this.toggleNodeIsExpanded(populatedNode);
                });

                return true;
            }

            return false;
        }

        /**
         * Ensures that the passed node is populated. After it is populated, the afterPopulated callback is invoked.
         */
        private ensureNodeChildrenPopulated(node: DynamicTocNode, afterPopulated: (populatedNode: DynamicTocNode) => void): void {
            if (node.cc) {
                if (!node.childNodes) {
                    // Node model needs to populate - it will expand once populated
                    this.loadNodeContainer(node.cc, () => {
                        afterPopulated(node);
                    });

                    return;
                } else {
                    if (!node.isPopulated) {
                        // Node model is populated, but the DOM elements have not been
                        //  created. Create them now
                        this.createElementsForNodeChildren(node);
                    }
                }
            }
            afterPopulated(node);
        }

        /**
         * Expand / collapse a node.
         */
        private toggleNodeIsExpanded(node: DynamicTocNode) {
            const spacer = $(`#i-n-${node.id} > ins`, this._rootSelector);
            spacer.toggleClass("i-expand i-collapse");
            spacer.siblings("ul").toggleClass("i-visible");

            if (this.getFeatureSettings().isIconEnabled) {
                // Update the icon for the 2 state icons
                const icon: JQuery = $(`#i-n-${node.id} > a > ins`, this._rootSelector);
                if (icon.hasClass("i-icon-1")) {
                    icon.removeClass("i-icon-1").addClass("i-icon-2");
                } else if (icon.hasClass("i-icon-2")) {
                    icon.removeClass("i-icon-2").addClass("i-icon-1");
                } else if (icon.hasClass("i-icon-3")) {
                    icon.removeClass("i-icon-3").addClass("i-icon-4");
                } else if (icon.hasClass("i-icon-4")) {
                    icon.removeClass("i-icon-4").addClass("i-icon-3");
                }
            }

            node.isExpanded = spacer.hasClass("i-collapse");
        }

        private getDefaultSettings(): IDynamicTocFeatureSettings {
            return {
                initialNodeContainer: null,
                initialNodeId: null,
                isIconEnabled: false,
                isEnabled: false,
                isResizable: true
            };
        }

        private getFeatureSettings(): IDynamicTocFeatureSettings {
            return this.documentInstance.getFeatureSettings<IDynamicTocFeatureSettings>("dynamictoc", this.getDefaultSettings);
        }

    }

    export interface IDynamicTocFeatureSettings {
        isIconEnabled: boolean;
        initialNodeId: string;
        initialNodeContainer: string;
        isEnabled: boolean;
        isResizable: boolean;
    }

    export class DynamicTocDocumentFeatureFactory {

        public createInstance(documentInstance: Document): IDocumentFeature {
            if (!Browser.isCompiledHelp()) {
                return new DynamicTocDocumentFeature(documentInstance);
            }
        }

    }

}

Innovasys.Content.DocumentFeatureConfiguration.registerDocumentFeatureFactory(
    new Innovasys.Content.Features.DynamicTocDocumentFeatureFactory());
